#!/usr/bin/env python3
from pathlib import Path

p = Path("apps/kernel/backend/authorization/Service.mo")
text = p.read_text()
if 'import List "mo:core/List";' not in text:
    text = text.replace(
        'import Iter "mo:core/Iter";\n',
        'import Iter "mo:core/Iter";\nimport List "mo:core/List";\n',
        1,
    )

old = '''        func listFromScope(\n            issuerScope : Types.AppScopeRef,\n        ) : [Types.AuthorizationGrant] {\n            if (\n                not CapabilityScope.valid(issuerScope) or\n                not scopeActive(issuerScope)\n            ) return [];\n            var result : [Types.AuthorizationGrant] = [];\n            for ((_, stored) in Map.entries(grantsMem.grants)) {\n                if (CapabilityScope.equal(stored.grant.issuer_scope, issuerScope)) {\n                    result := Array.concat(result, [stored.grant]);\n                };\n            };\n            result;\n        };\n'''
new = '''        func listFromScope(\n            issuerScope : Types.AppScopeRef,\n        ) : [Types.AuthorizationGrant] {\n            if (\n                not CapabilityScope.valid(issuerScope) or\n                not scopeActive(issuerScope)\n            ) return [];\n            let ?currentSubject = scopeSubject(issuerScope) else return [];\n            if (not subjectOwnsScope(currentSubject, issuerScope)) return [];\n            let result = List.empty<Types.AuthorizationGrant>();\n            for ((_, stored) in Map.entries(grantsMem.grants)) {\n                if (\n                    CapabilityScope.equal(stored.grant.issuer_scope, issuerScope) and\n                    stored.grant.issuer_subject == currentSubject\n                ) {\n                    List.add(result, stored.grant);\n                };\n            };\n            List.toArray(result);\n        };\n'''
if old not in text:
    raise SystemExit("listFromScope target missing")
text = text.replace(old, new, 1)

old = '''            if (\n                grant.revoked_at != null or\n                isExpired(grant.expires_at) or\n                not grantEpochCurrent(grant) or\n                not scopeActive(grant.provider_scope)\n            ) return false;\n'''
new = '''            if (\n                grant.revoked_at != null or\n                isExpired(grant.expires_at) or\n                not grantEpochCurrent(grant) or\n                not scopeActive(grant.provider_scope) or\n                not scopeActive(grant.issuer_scope) or\n                not subjectOwnsScope(grant.issuer_subject, grant.issuer_scope)\n            ) return false;\n'''
if old not in text:
    raise SystemExit("grantUsable guard target missing")
text = text.replace(old, new, 1)

old = '''                    if (\n                        parent.revoked_at != null or\n                        isExpired(parent.expires_at) or\n                        not grantEpochCurrent(parent) or\n                        not resourceEqual(parent.resource, original.resource) or\n                        not CapabilityScope.equal(\n                            parent.provider_scope,\n                            original.provider_scope,\n                        )\n                    ) return false;\n'''
new = '''                    if (\n                        parent.revoked_at != null or\n                        isExpired(parent.expires_at) or\n                        not grantEpochCurrent(parent) or\n                        not scopeActive(parent.issuer_scope) or\n                        not subjectOwnsScope(parent.issuer_subject, parent.issuer_scope) or\n                        not resourceEqual(parent.resource, original.resource) or\n                        not CapabilityScope.equal(\n                            parent.provider_scope,\n                            original.provider_scope,\n                        )\n                    ) return false;\n'''
if old not in text:
    raise SystemExit("ancestryUsable guard target missing")
text = text.replace(old, new, 1)

old = '''        func effectivelyRevoked(grant : Types.AuthorizationGrant) : Bool {\n            if (grant.revoked_at != null or not grantEpochCurrent(grant)) {\n                return true;\n            };\n            ancestryRevoked(grant, 0);\n        };\n'''
new = '''        func effectivelyRevoked(grant : Types.AuthorizationGrant) : Bool {\n            if (\n                grant.revoked_at != null or\n                not grantEpochCurrent(grant) or\n                not scopeActive(grant.issuer_scope) or\n                not subjectOwnsScope(grant.issuer_subject, grant.issuer_scope)\n            ) return true;\n            ancestryRevoked(grant, 0);\n        };\n'''
if old not in text:
    raise SystemExit("effectivelyRevoked target missing")
text = text.replace(old, new, 1)

old = '''                    if (\n                        parent.revoked_at != null or\n                        not grantEpochCurrent(parent)\n                    ) return true;\n'''
new = '''                    if (\n                        parent.revoked_at != null or\n                        not grantEpochCurrent(parent) or\n                        not scopeActive(parent.issuer_scope) or\n                        not subjectOwnsScope(parent.issuer_subject, parent.issuer_scope)\n                    ) return true;\n'''
if old not in text:
    raise SystemExit("ancestryRevoked guard target missing")
text = text.replace(old, new, 1)

old = '''            let leaseRandom = await* freshRandom();\n            if (leaseRandom.size() < 32) return #err(#unavailable);\n            let leaseId = hex(leaseRandom);\n            let issuedAt = now();\n            let nominalLeaseExpiry = issuedAt + LEASE_LIFETIME_NS;\n            let effectiveLeaseExpiry = switch (grant.expires_at) {\n                case (?grantExpiry) {\n                    if (grantExpiry < nominalLeaseExpiry) grantExpiry\n                    else nominalLeaseExpiry;\n                };\n                case null nominalLeaseExpiry;\n            };\n            let lease : Types.AuthorizationLease = {\n                lease_id = leaseId;\n                grant_id = grant.grant_id;\n                subject;\n                consumer_scope = input.consumer_scope;\n                provider_scope = grant.provider_scope;\n                resource = grant.resource;\n                rights = grant.rights;\n                issued_at = issuedAt;\n                expires_at = effectiveLeaseExpiry;\n            };\n\n            let updatedGrant = copyGrantWithRedemptionCount(\n                grant,\n                grant.redemption_count + 1,\n            );\n            Map.add(\n                grantsMem.grants,\n                Text.compare,\n                grant.grant_id,\n                { grant = updatedGrant; secret_hash = stored.secret_hash },\n            );\n            Map.add(leases, Text.compare, leaseId, lease);\n            appendAudit(\n                "redeem",\n                ?grant.grant_id,\n                ?subject,\n                ?input.consumer_scope,\n                ?grant.provider_scope,\n                ?grant.resource,\n            );\n'''
new = '''            let leaseRandom = await* freshRandom();\n            if (leaseRandom.size() < 32) return #err(#unavailable);\n\n            // raw_rand/freshRandom is an await boundary. Re-read and revalidate\n            // the grant after it so concurrent revocation, epoch rotation,\n            // ownership changes, expiry, or redemption-limit consumption cannot\n            // be bypassed by an in-flight redemption. No await occurs between\n            // this final check and the persistent redemption-count increment.\n            let ?currentStored = Map.get(\n                grantsMem.grants,\n                Text.compare,\n                token.grant_id,\n            ) else return #err(#denied);\n            if (not secretMatches(\n                token.grant_id,\n                token.secret,\n                currentStored.secret_hash,\n            )) return #err(#denied);\n            let currentGrant = currentStored.grant;\n            if (\n                not grantUsable(currentGrant) or\n                not audienceAllows(currentGrant.audience, subject) or\n                not CapabilityScope.valid(input.consumer_scope) or\n                not scopeActive(input.consumer_scope) or\n                not subjectOwnsScope(subject, input.consumer_scope) or\n                not scopeActive(currentGrant.provider_scope) or\n                not consumerElementAllows(\n                    currentGrant.consumer_element,\n                    input.consumer_scope,\n                ) or\n                not redemptionAvailable(currentGrant)\n            ) return #err(#denied);\n\n            let leaseId = hex(leaseRandom);\n            let issuedAt = now();\n            let nominalLeaseExpiry = issuedAt + LEASE_LIFETIME_NS;\n            let effectiveLeaseExpiry = switch (currentGrant.expires_at) {\n                case (?grantExpiry) {\n                    if (grantExpiry < nominalLeaseExpiry) grantExpiry\n                    else nominalLeaseExpiry;\n                };\n                case null nominalLeaseExpiry;\n            };\n            let lease : Types.AuthorizationLease = {\n                lease_id = leaseId;\n                grant_id = currentGrant.grant_id;\n                subject;\n                consumer_scope = input.consumer_scope;\n                provider_scope = currentGrant.provider_scope;\n                resource = currentGrant.resource;\n                rights = currentGrant.rights;\n                issued_at = issuedAt;\n                expires_at = effectiveLeaseExpiry;\n            };\n\n            let updatedGrant = copyGrantWithRedemptionCount(\n                currentGrant,\n                currentGrant.redemption_count + 1,\n            );\n            Map.add(\n                grantsMem.grants,\n                Text.compare,\n                currentGrant.grant_id,\n                { grant = updatedGrant; secret_hash = currentStored.secret_hash },\n            );\n            Map.add(leases, Text.compare, leaseId, lease);\n            appendAudit(\n                "redeem",\n                ?currentGrant.grant_id,\n                ?subject,\n                ?input.consumer_scope,\n                ?currentGrant.provider_scope,\n                ?currentGrant.resource,\n            );\n'''
if old not in text:
    raise SystemExit("redeem post-await target missing")
text = text.replace(old, new, 1)

old = '''        func normalizeRights(\n            rights : [Types.ResourceRight],\n        ) : [Types.ResourceRight] {\n            var result : [Types.ResourceRight] = [];\n            let allRights : [Types.ResourceRight] = [#read, #write, #reshare];\n            for (right in allRights.vals()) {\n                if (hasRight(rights, right)) result := Array.concat(result, [right]);\n            };\n            result;\n        };\n'''
new = '''        func normalizeRights(\n            rights : [Types.ResourceRight],\n        ) : [Types.ResourceRight] {\n            let allRights : [Types.ResourceRight] = [#read, #write, #reshare];\n            Array.filter<Types.ResourceRight>(\n                allRights,\n                func(right : Types.ResourceRight) : Bool {\n                    hasRight(rights, right);\n                },\n            );\n        };\n'''
if old not in text:
    raise SystemExit("normalizeRights target missing")
text = text.replace(old, new, 1)

p.write_text(text)
